/* eslint no-console:0 import/extensions:0 */
import 'fantd/src/button/style/index.less';
import { Button } from 'fantd';
import React from 'react';
import ReactDOM from 'react-dom';
import "./button.less";

class Component extends React.Component {

    state = {
        loading:false
    }
    render() {
        return (
            <div>
                <div style={{ margin: 10 }}>
                    <Button size="large">操作</Button>
                    <Button size="large" disabled>操作</Button>
                    <Button size="large" loading>操作</Button>
                    <br />
                    <Button >操作</Button>
                    <Button disabled>操作</Button>
                    <Button loading>操作</Button>
                    <br />
                    <Button size="small">操作</Button>
                    <Button size="small" disabled>操作</Button>
                    <Button size="small" loading>操作</Button>
                </div>
                <div style={{ margin: 10 }} >
                    <Button type="light" size="large">操作</Button>
                    <Button type="light" size="large" disabled>操作</Button>
                    <Button type="light" size="large" loading>操作</Button>
                    <br />
                    <Button type="light" >操作</Button>
                    <Button type="light" disabled>操作</Button>
                    <Button type="light" loading>操作</Button>
                    <br />
                    <Button type="light" size="small">操作</Button>
                    <Button type="light" size="small" disabled>操作</Button>
                    <Button type="light" size="small" loading>操作</Button>
                </div>
                <div style={{ margin: 10 }} >
                    <Button type="plain" size="large">操作</Button>
                    <Button type="plain" size="large" disabled>操作</Button>
                    <Button type="plain" size="large" loading>操作</Button>
                    <br />
                    <Button type="plain" >操作</Button>
                    <Button type="plain" disabled>操作</Button>
                    <Button type="plain" loading>操作</Button>
                    <br />
                    <Button type="plain" size="small">操作</Button>
                    <Button type="plain" size="small" disabled>操作</Button>
                    <Button type="plain" size="small" loading>操作</Button>
                </div>
                <div style={{ margin: 10 }}>
                    <Button
                        size="large"
                        loading={this.state.loading}
                        onClick={() => {
                            this.setState({
                                loading:true,
                            },() => {
                                setTimeout(() => {
                                    this.setState({
                                        loading:false,
                                    })
                                },2000)
                            })
                        }}
                    >操作操作操作操作操作操作
                    </Button>
                    <Button
                        size="small"
                        loading={this.state.loading}
                        onClick={() => {
                            this.setState({
                                loading:true,
                            },() => {
                                setTimeout(() => {
                                    this.setState({
                                        loading:false,
                                    })
                                },2000)
                            })
                        }}
                    >操作
                    </Button>
                    <Button
                        size="default"
                        disabled
                        loading={this.state.loading}
                        onClick={() => {
                            this.setState({
                                loading:true,
                            },() => {
                                setTimeout(() => {
                                    this.setState({
                                        loading:false,
                                    })
                                },2000)
                            })
                        }}
                    >操作
                    </Button>
                    <Button
                        size="default"
                        type="plain"
                        loading={this.state.loading}
                        onClick={() => {
                            this.setState({
                                loading:true,
                            },() => {
                                setTimeout(() => {
                                    this.setState({
                                        loading:false,
                                    })
                                },2000)
                            })
                        }}
                    >操作
                    </Button>
                </div>
            </div>
        );
    }
}

ReactDOM.render(<Component />, document.getElementById('__react-content'));



